// Записывает видео из canvas + подмешивает аудио с <video>
// ⟶ новое видео без старых метаданных; можно добавить шум; можно «съесть» 1-й/последний кадр

/* ===== per-button progress (dim + fill) ===== */
/* ===== per-button progress (dim + fill + percent) ===== */
const BTN_CSS_ID = 'alh-btn-progress-style';

function ensureBtnStyles() {
  if (document.getElementById(BTN_CSS_ID)) return;
  const css = `
  .alh-btn-loading { position: relative; overflow: hidden; }
  .alh-btn-loading .alh-btn-fill {
    position: absolute; left: 0; top: 0; bottom: 0; width: 0%;
    background: rgba(0,0,0,.35);
    transition: width .12s linear;
    pointer-events: none;
  }
  .alh-btn-loading .alh-btn-pct {
    position: absolute; right: 8px; top: 50%; transform: translateY(-50%);
    font: 11px/1 system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,Arial;
    color: #fff; text-shadow: 0 1px 2px rgba(0,0,0,.5);
    pointer-events: none;
  }`;
  const style = document.createElement('style');
  style.id = BTN_CSS_ID;
  style.textContent = css;
  document.documentElement.appendChild(style);
}

/** Создаёт контроллер прогресса для кнопки */
export function makeButtonProgress(btn) {
  if (!btn) return { set: ()=>{}, done: ()=>{}, fail: ()=>{} };
  ensureBtnStyles();

  btn.classList.add('alh-btn-loading');
  const fill = document.createElement('div');
  fill.className = 'alh-btn-fill';
  const pctLabel = document.createElement('div');
  pctLabel.className = 'alh-btn-pct';
  pctLabel.textContent = '0%';
  btn.appendChild(fill);
  // btn.appendChild(pctLabel);
  // btn.prepend(pctLabel);

  const prevPE = btn.style.pointerEvents;
  btn.style.pointerEvents = 'none';

  const set = (pct) => {
    const p = Math.max(0, Math.min(100, pct || 0));
    fill.style.width = `${p}%`;
    pctLabel.textContent = `${Math.round(p)}%`;
    // лёгкое затемнение самой кнопки по мере прогресса (при желании можно убрать)
    btn.style.filter = `grayscale(${Math.min(0.6, p/100)}) brightness(${1 - 0.3*(p/100)})`;
  };

  const cleanup = () => {
    btn.style.pointerEvents = prevPE || '';
    btn.style.filter = '';
    fill.remove();
    pctLabel.remove();
    btn.classList.remove('alh-btn-loading');
  };

  const done = () => { set(100); setTimeout(cleanup, 280); };
  const fail = () => { cleanup(); };

  set(0);
  return { set, done, fail };
}

// --- вспомогалки кривых (плавные нелинейные росты) ---
const clamp01 = (x) => Math.min(1, Math.max(0, x));
const ease = (x, k = 1.2) => Math.pow(clamp01(x), k);          // мягкий рост
const smoothstep = (x) => x * x * (3 - 2 * x);                 // S-кривая

// Маппинг параметров шума из s = [0..1]
function noiseParams(s) {
  s = clamp01(s);

  // 1) Покрытие (доля «шумных» пикселей): мягко растёт от ~2% до ~90%
  const coverage = 0.02 + 0.88 * ease(s, 1.1);   // 0.1 → ~0.09, 0.2 → ~0.17, 0.3 → ~0.25, …

  // 2) Контраст (насколько сильный разброс яркости шумных пикселей)
  const contrast = 0.15 + 0.85 * smoothstep(s);  // 0.1 → 0.16, 0.2 → 0.23, 0.3 → 0.32 … 1.0 → 1.0

  // 3) Прозрачность «зерна» (альфа, 0..255), слегка растёт,
  //    но не даём сразу 255, чтобы низкие значения были деликатнее
  const alpha = Math.round(40 + 190 * ease(s, 1.3)); // 0.1 → ~61, 0.2 → ~82, 0.3 → ~103 … 1.0 → 230

  // 4) Шаг подсетки (размер зерна): от 2px к 1px
  //    на очень малых значениях допускаем чуть «крупнее», чтобы было ещё «мягче»
  const step = Math.max(1, Math.round(2 - 1 * s));  // 0..0.49 → 2px, 0.5..1 → 1px

  return { coverage, contrast, alpha: s <= 0.4 ? alpha / 2 : alpha, step };
}

// --- обновлённый генератор шума ---
// nctx: контекст noiseCanvas, width/height — размеры
function drawNoiseSmart(nctx, width, height, s) {
  if (s <= 0) return;
  const { coverage, contrast, alpha, step } = noiseParams(s);

  const id = nctx.createImageData(width, height);
  const data = id.data;

  // Для «контраста»: берём случай v в [0..1], а потом притягиваем к 0 или 1:
  // v' = mix(0.5, v, contrast) и ещё один шаг к «краям».
  // Так при маленьком контрасте шум ближе к серому, при большом — к чисто ч/б.
  const pushContrast = (v) => {
    const mid = 0.5 + (v - 0.5) * contrast;
    // дополнительный «щёлк» к краям
    return clamp01(0.5 + (mid - 0.5) * (0.85 + 0.15 * contrast));
  };

  // Идём по сетке с шагом step, остальное оставляем прозрачным
  for (let y = 0; y < height; y += step) {
    for (let x = 0; x < width; x += step) {
      if (Math.random() < coverage) {
        // серый с контрастом
        const v = pushContrast(Math.random());
        const g = Math.round(v * 255);
        // заполняем ячейку step x step
        for (let yy = 0; yy < step; yy++) {
          const py = y + yy; if (py >= height) break;
          for (let xx = 0; xx < step; xx++) {
            const px = x + xx; if (px >= width) break;
            const i = (py * width + px) * 4;
            data[i] = g;
            data[i + 1] = g;
            data[i + 2] = g;
            data[i + 3] = alpha;
          }
        }
      } // иначе блок остаётся полностью прозрачным
    }
  }
  nctx.putImageData(id, 0, 0);
}

function pickBestMime() {
  const preference = [
    "video/mp4;codecs=avc1.42E01E,mp4a.40.2", // Safari
    "video/mp4",
    "video/webm;codecs=vp9,opus",
    "video/webm;codecs=vp8,opus",
    "video/webm"
  ];
  return preference.find(mt => MediaRecorder.isTypeSupported(mt)) || "";
}

export function extForMime(mime) {
  if (!mime) return 'webm'; // дефолт

  mime = mime.toLowerCase();
  if (mime.includes('webm')) return 'webm';
  if (mime.includes('mp4')) return 'mp4';
  if (mime.includes('ogg') || mime.includes('ogv')) return 'ogv';
  if (mime.includes('x-matroska') || mime.includes('mkv')) return 'mkv';

  return 'webm'; // fallback
}


export async function processVideoWithMediaRecorder(inputBlob, options = {}) {
  const {
    // визуал
    noiseStrength = 0.1,    // 0..1 — Вероятность закраски пикселя шумом. 0 — без шума.
    noiseAlpha    = 200,    // 0..255 — прозрачность «шумного» пикселя (фиксированная)
    fps = 30,
    dropFirstFrame,
    dropLastFrame,
    format,

    // запись
    playbackRate   = 1.0,   // >1 ускоряет запись и само видео (звук ускорится/исказится!)
    preferVP9      = true,
    videoBitsPerSecond = 3_000_000,
    audioBitsPerSecond = 128_000,

    // прогресс
    onProgress = null       // ({ pct, etaSec, phase }) => void
  } = options;

  // === init ===
  const srcUrl = URL.createObjectURL(inputBlob);
  const video = document.createElement('video');
  video.src = srcUrl;
  video.playsInline = true;
  video.muted = true;              // для автоплея
  video.crossOrigin = 'anonymous';
  video.playbackRate = playbackRate;

  onProgress?.({ pct: 0, etaSec: NaN, phase: 'init' });

  await new Promise((res, rej) => {
    video.onloadedmetadata = res;
    video.onerror = () => rej(new Error('Failed to load video metadata'));
  });

  const width  = video.videoWidth  || 640;
  const height = video.videoHeight || 360;

  // === canvas + noise ===
  const canvas = document.createElement('canvas');
  canvas.width = width; canvas.height = height;
  const ctx = canvas.getContext('2d', { alpha: false });

  const noiseCanvas = document.createElement('canvas');
  noiseCanvas.width = width; noiseCanvas.height = height;
  const nctx = noiseCanvas.getContext('2d');

  // Новый генератор шума: редкость шума зависит от noiseStrength
  const drawNoise = () => {
    if (noiseStrength <= 0) return;

    const id = nctx.createImageData(width, height);
    const data = id.data;
    const probability = noiseStrength;     // шанс, что пиксель будет шумным
    const alpha = 200;                     // прозрачность зерна (0–255)

    for (let i = 0; i < data.length; i += 4) {
      if (Math.random() < probability) {
        const v = (Math.random() * 255) | 0;   // случайный оттенок серого
        data[i] = v;
        data[i + 1] = v;
        data[i + 2] = v;
        data[i + 3] = alpha;
      } else {
        data[i + 3] = 0;   // полностью прозрачный пиксель
      }
    }
    nctx.putImageData(id, 0, 0);
  };

  const drawFrame = () => {
    ctx.drawImage(video, 0, 0, width, height);
    if (noiseStrength > 0) {
      // drawNoise();
      drawNoiseSmart(nctx, width, height, noiseStrength);
      ctx.drawImage(noiseCanvas, 0, 0);
    }
  };

  // === формируем поток: видео из canvas, аудио из captureStream/WebAudio ===
  const canvasStream = canvas.captureStream(fps);
  let audioTrack = null;

  try {
    const vStream = typeof video.captureStream === 'function' ? video.captureStream() : null;
    if (vStream) {
      const ats = vStream.getAudioTracks();
      if (ats && ats.length) audioTrack = ats[0];
    }
  } catch {}

  if (!audioTrack) {
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      const ac = new AC();
      if (ac.state === 'suspended') { try { await ac.resume(); } catch {} }
      const srcNode = ac.createMediaElementSource(video);
      const dest = ac.createMediaStreamDestination();
      srcNode.connect(dest);
      const t = dest.stream.getAudioTracks()[0];
      if (t) audioTrack = t;
    } catch {}
  }

  const tracks = [canvasStream.getVideoTracks()[0]];
  if (audioTrack) tracks.push(audioTrack);
  const combinedStream = new MediaStream(tracks);

  // === выбор MIME ===
  const mimeWithAudio = preferVP9 ? 'video/webm;codecs=vp9,opus' : 'video/webm;codecs=vp8,opus';
  const mimeVideoOnly = preferVP9 ? 'video/webm;codecs=vp9'     : 'video/webm;codecs=vp8';
  const wantMime = audioTrack ? mimeWithAudio : mimeVideoOnly;

  // const mime = format === 'mp4' ? 'video/mp4' : MediaRecorder.isTypeSupported(wantMime)
  //   ? wantMime
  //   : (audioTrack
  //     ? (MediaRecorder.isTypeSupported('video/webm;codecs=vp8,opus') ? 'video/webm;codecs=vp8,opus' : 'video/webm')
  //     : (MediaRecorder.isTypeSupported('video/webm;codecs=vp8') ? 'video/webm;codecs=vp8' : 'video/webm'));

  const mime = pickBestMime();
  const mrInit = {
    videoBitsPerSecond,
    audioBitsPerSecond
  };

  if (mime) {
    mrInit.mimeType = mime
  } else {
    console.log('mime not found');
  }

  const mr = new MediaRecorder(combinedStream, mrInit);

  const chunks = [];
  mr.ondataavailable = (e) => { if (e.data && e.data.size) chunks.push(e.data); };

  const waitEvent = (target, name) => new Promise((res) => {
    const once = () => { target.removeEventListener(name, once); res(); };
    target.addEventListener(name, once);
  });

  // === прогресс ===
  const duration = video.duration || 0;
  const frameMs = 1000 / fps;
  let progTimer = null;

  const startProgressLoop = () => {
    onProgress?.({ pct: 0, etaSec: isFinite(duration) ? duration : NaN, phase: 'recording' });
    if (!duration || !isFinite(duration)) return; // без ETA, но всё равно будем слать фазы
    progTimer = setInterval(() => {
      const cur = video.currentTime || 0;
      const pct = Math.max(0, Math.min(100, (cur / duration) * 100));
      const left = Math.max(0, duration - cur);
      const etaSec = left / (playbackRate || 1);
      onProgress?.({ pct, etaSec, phase: 'recording' });
    }, 200);
  };

  // === цикл рендера ===
  let rafId = 0, recording = false, stopRequested = false;

  const startAfterFirstFrame = async () => {
    // ждём первый реальный кадр
    await new Promise((r) => {
      const onTU = () => { video.removeEventListener('timeupdate', onTU); r(); };
      video.addEventListener('timeupdate', onTU, { once: true });
    });
    if (dropFirstFrame) await new Promise(r => setTimeout(r, frameMs));
    mr.start(1000); // чанки раз в секунду
    recording = true;
    startProgressLoop();
  };

  const loop = async () => {
    if (stopRequested) return;
    drawFrame();
    if (!recording) await startAfterFirstFrame();
    rafId = requestAnimationFrame(loop);
  };

  // === запуск ===
  onProgress?.({ pct: 0, etaSec: NaN, phase: 'starting' });
  await video.play();
  loop();

  // точка остановки (на 1 кадр раньше, если надо)
  const totalMs = (duration * 1000) / (playbackRate || 1);
  const stopEarly = dropLastFrame ? frameMs : 0;
  await new Promise(r => setTimeout(r, Math.max(0, totalMs - stopEarly)));

  // === остановка ===
  stopRequested = true;
  cancelAnimationFrame(rafId);
  if (recording && mr.state !== 'inactive') mr.stop();
  await waitEvent(mr, 'stop').catch(() => {});

  if (progTimer) clearInterval(progTimer);
  onProgress?.({ pct: 100, etaSec: 0, phase: 'finalizing' });

  // === финал ===
  URL.revokeObjectURL(srcUrl);
  canvasStream.getTracks().forEach(t => t.stop());
  if (audioTrack && audioTrack.stop) { try { audioTrack.stop(); } catch {} }

  const outBlob = new Blob(chunks, { type: mime });
  onProgress?.({ pct: 100, etaSec: 0, phase: 'done' });
  return {outBlob, format};
}
