/*global chrome*/
import { options } from './optionsStore.js';

const sortTypeShows = 'shows';
const sortTypeCreative = 'creative';
const getAccountId = () => {
  let regText = /"ACCOUNT_ID":"(\d+)"/;
  let matchReg = regText.exec(document.documentElement.innerHTML);

  return matchReg[1];
}

const joinObject = (obj) => {
  return Object.entries(obj)
    .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
    .join('&');
}

const searchTokens = (arr) => {
  const lsdText = '"LSD",';
  const dtsgText = '"DTSGInitialData",';

  let indexLsdToken = 0;
  let indexDtsgToken = 0;

  arr.forEach((el, index) => {
    if (el.includes(lsdText)) {
      indexLsdToken = index + 1;
    }
    if (el.includes(dtsgText)) {
      indexDtsgToken = index + 1;
    }
  });

  return {
    indexLsdToken,
    indexDtsgToken,
  };
}

const getTokens = () => {
  // Получаем текст всех скриптов на странице
  const scripts = document.querySelectorAll("script");

  let scriptTexts = "";
  scripts.forEach(script => {
    scriptTexts += script.textContent;
  });
  const textBodyScript = scriptTexts.split("[");

  const {indexLsdToken, indexDtsgToken} = searchTokens(textBodyScript);
  const tokenLsd = textBodyScript[indexLsdToken];
  const tokenDtsg = textBodyScript[indexDtsgToken];

  const str1 = new RegExp('],{"token":"', "g");
  const str2 = new RegExp('"},323],', "g");
  const str3 = new RegExp('"},258],', "g");

  return {
    lsdToken: tokenLsd.replace(str1, '').replace(str2, ''),
    dtsgToken: tokenDtsg.replace(str1, '').replace(str3, '')
  };
}

const getTotalReach = async (id) => {
  try {
    const {lsdToken, dtsgToken} = getTokens();
    const accountId = getAccountId();

    const response = await fetch('/api/graphql/', {
      method: 'POST',
      headers: {
        'accept': '*/*',
        'content-type': 'application/x-www-form-urlencoded',
      },
      body: joinObject({
        'av': accountId,
        '__user': accountId,
        '__csr': '',
        'fb_dtsg': dtsgToken,
        'lsd': lsdToken,
        'variables': '{"adArchiveID":"' + id + '","pageID":"","country":"ALL","sessionID":"","source":null,"isAdNonPolitical":true,"isAdNotAAAEligible":false}',
        'server_timestamps': 'true',
        'doc_id': '6635716889819821'
      }),
      mode: 'same-origin',
      credentials: 'include'
    });

    const data = await response.json();

    if (data && data.data && data.data.ad_library_main && data.data.ad_library_main.ad_details && data.data.ad_library_main.ad_details.aaa_info) {
      return data.data.ad_library_main.ad_details.aaa_info.eu_total_reach;
    } else {
      return null;
      // return data.errors[0].summary;
    }
  } catch (e) {
    console.error('Error getTotalReach:', e);
    return null;
  }
}

const toSnakeCase = (str) =>{
  return str
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .toLowerCase();
}

const transformKeysToSnakeCase = (obj) => {
  if (!obj) {
    return;
  }
  if (Array.isArray(obj)) {
    return obj.map(transformKeysToSnakeCase);
  }

  if (obj !== null && typeof obj === 'object') {
    const newObj = {};
    for (const key in obj) {
      const snakeKey = toSnakeCase(key);
      newObj[snakeKey] = transformKeysToSnakeCase(obj[key]);
    }
    return newObj;
  }

  return obj;
}

const extractPageData = () => {
  const scripts = document.querySelectorAll('script[type="application/json"][data-sjs]');
  let adData = [];
  const adSoloModal = [];
  scripts.forEach(script => {
    try {
      const jsonData = JSON.parse(script.textContent);
      const edges = jsonData?.require?.[0]?.[3]?.[0]?.__bbox?.require?.[0]?.[3]?.[1]?.__bbox?.result?.data?.ad_library_main?.search_results_connection?.edges;
      const edgeSolo = jsonData?.require?.[0]?.[3]?.[0]?.__bbox?.require?.[0]?.[3]?.[1]?.__bbox?.result?.data?.ad_library_main?.deeplink_ad_archive_result?.deeplink_ad_archive;

      if (edges) {
        edges.forEach(edge => {
          if (edge?.node?.collated_results) {
            adData = adData.concat(edge.node.collated_results);
          }
        });
      } else if (jsonData.require?.[0]?.[3]?.[0]?.__bbox?.require?.[6]?.[3]?.[0]?.entryPointRoot.otherProps.deeplinkAdCard) {

        const transformed = transformKeysToSnakeCase(jsonData.require?.[0]?.[3]?.[0]?.__bbox?.require?.[6]?.[3]?.[0]?.entryPointRoot?.otherProps?.deeplinkAdCard);
        if (transformed) {
          adData.push(transformed);
        }
      }
      if (edgeSolo && adSoloModal.length === 0) {
        adSoloModal.push(edgeSolo)
      }
    } catch (error) {
      console.error('Error parsing JSON:', error);
    }
  });

  return [...adSoloModal, ...adData];
};

const extractAds = (edges) => {
  let ads = [];
  if (!Array.isArray(edges)) {
    return ads;
  }

  edges.forEach(edge => {
    if (edge?.node?.collated_results) {
      ads = ads.concat(edge.node.collated_results);
    }
    if (edge?.ad_archive_id) {
      ads.push(edge);
    }
  });
  return ads;
}

const extractEdges = (jsonData) => {
  if (jsonData?.label?.includes('AdLibraryMobileFocusedStateProvider')) {
    return jsonData?.data?.ad_library_main?.search_results_connection?.edges;
  }

  if (jsonData?.data?.ad_library_main?.collation_results?.ad_cards?.length) {

    return jsonData?.data?.ad_library_main?.collation_results?.ad_cards;
  }

  return jsonData?.data?.ad_library_main?.search_results_connection?.edges;
};

const processAdData = (ads) => {
  if (!ads?.length) {
    return;
  }

  return ads.map(ad => {
    const processedAd = {
      collation_count: ad.collation_count,
      ad_archive_id: ad.ad_archive_id,
      page_id: ad.page_id,
      display_format: ad.snapshot.display_format,
      start_date: new Date(ad.start_date * 1000).toISOString(),
      end_date: new Date(ad.end_date * 1000).toISOString(),
      pageName: ad.snapshot.page_name,
      pageLink: ad.snapshot.page_profile_uri,
      profilePicture: ad.snapshot.page_profile_picture_url,
      rawData: ad,
    };

    if (ad.snapshot.display_format === 'IMAGE') {
      processedAd.original_image_url = ad.snapshot.images[0]?.original_image_url || null;
      processedAd.media_type = 'IMAGE';
      processedAd.link_url = ad.snapshot.link_url;
      processedAd.cta_text = ad.snapshot.cta_text;
    } else if (ad.snapshot.display_format === 'VIDEO') {
      const video = ad.snapshot.videos[0];
      processedAd.video_hd_url = video?.video_hd_url || video?.video_sd_url || null;
      processedAd.media_type = 'VIDEO';
      processedAd.link_url = ad.snapshot.link_url;
      processedAd.cta_text = ad.snapshot.cta_text;

    } else if (ad.snapshot.display_format === 'DCO') {
      const cardWithMedia = ad.snapshot.cards.find(
        card => card.original_image_url || card.video_hd_url
      );
      if (cardWithMedia) {
        if (cardWithMedia.original_image_url) {
          processedAd.original_image_url = cardWithMedia.original_image_url;
          processedAd.media_type = 'IMAGE';
          processedAd.link_url = cardWithMedia.link_url;
          processedAd.cta_text = cardWithMedia.cta_text;
        } else {
          processedAd.video_hd_url = cardWithMedia.video_hd_url || cardWithMedia.video_sd_url;
          processedAd.media_type = 'VIDEO';
          processedAd.link_url = cardWithMedia.link_url;
          processedAd.cta_text = cardWithMedia.cta_text;
        }
      }
    } else if (ad.snapshot.display_format === 'CAROUSEL') {
      const {images, videos} = ad?.snapshot?.cards?.reduce(
        (acc, card) => {
          if (card.original_image_url) {
            acc.images.push({
              original_image_url: card.original_image_url,
              link_url: card.link_url,
              cta_text: card.cta_text,
              media_type: 'IMAGE'
            });
            return acc;
          }
          if (card.video_hd_url) {
            acc.videos.push({
              video_hd_url: card.video_hd_url,
              link_url: card.link_url,
              cta_text: card.cta_text,
              media_type: 'VIDEO',
            });
            return acc;
          }
          return acc;
        },
        {images: [], videos: []}
      );

      processedAd.imageURLs = images;
      processedAd.videoURLs = videos;
    } else if (ad.snapshot.display_format === 'DPA') {
      const card = ad?.snapshot?.cards[0];
      const videoURl = card?.video_hd_url || card?.video_sd_url;
      const imageURl = card?.original_image_url;
      if (imageURl) {
        processedAd.original_image_url = imageURl;
        processedAd.media_type = 'IMAGE';
        processedAd.link_url = card.link_url;
        processedAd.cta_text = card.cta_text;
      }
      if (videoURl) {
        processedAd.video_hd_url = videoURl;
        processedAd.media_type = 'VIDEO';
        processedAd.link_url = card.link_url;
        processedAd.cta_text = card.cta_text;
      }
    }

    // if (ad?.snapshot?.link_url) {
    //   processedAd.link_url = ad.snapshot.link_url;
    // }
    //
    // if (ad?.snapshot?.cta_text) {
    //   processedAd.cta_text = ad.snapshot.cta_text;
    // }

    return processedAd;
  });
};


const processGraphQLResponse = (response, rawAds, ads) => {
  try {
    let jsonObjects = [];
    const responseAds = []

    if (typeof response === 'string') {
      const lines = response.split('\n');
      for (const line of lines) {
        if (!line.trim()) continue;
        try {
          jsonObjects.push(JSON.parse(line));
        } catch (e) {
          console.warn('Failed to parse JSON line:', e);
        }
      }
    } else if (typeof response === 'object') {
      jsonObjects = [response];
    }

    for (const jsonData of jsonObjects) {
      const edges = extractEdges(jsonData);
      if (!edges) continue;

      const newAds = extractAds(edges);
      if (newAds.length === 0) continue;
      rawAds.push(...newAds)
      const processedAds = processAdData(newAds);
      responseAds.push(...processedAds);
      ads.push(...processedAds);
    }
    return responseAds;
  } catch (error) {
    console.error('Error in processGraphQLResponse:', error);
  }
};

