const debounce = (fn, delay = 300) => {
  let timeout;

  const debounced = function (...args) {
    clearTimeout(timeout);

    if (fn) {
      timeout = setTimeout(() => fn.apply(this, args), delay);
    }
  };

  debounced.cancel = () => clearTimeout(timeout);

  return debounced;
};

const sort = (sortType) => {
  if (!sortType) {
    console.log('typeof sort unknown');
    return;
  }

  const attributeBySort = sortType === sortTypeCreative ? 'count-creative' : 'data-shows';
  const classBySort = 'parentItemAdsMeta';

  try {
    const containers = document.querySelectorAll('.sortableAdMain');

    containers?.forEach(container => {
      if (container) {
        const minShowValue = sortType === sortTypeCreative ? filter.limitCreative : filter.limit;

        const allItems = Array.from(container.querySelectorAll('.parentItemAdsMeta'));

        const sortableItems = allItems
          .filter(item => item.classList.contains(classBySort))
          .filter(item => {
            const val = Number(item.getAttribute(attributeBySort));
            return !isNaN(val) && val >= minShowValue;
          });

        sortableItems.sort((a, b) => {
          const aVal = Number(a.getAttribute(attributeBySort));
          const bVal = Number(b.getAttribute(attributeBySort));
          return bVal - aVal;
        });

        sortableItems.forEach(el => {
          container.appendChild(el);
        });
      }
    });

    applyLimit();
  } catch (err) {
    console.error('Ошибка при сортировке элементов:', err);
  }
}

const applyLimit = () => {
  const classBySort = 'parentItemAdsMeta';
  const attributeCreative = 'count-creative';
  const attributeShows = 'data-shows';

  const allItems = Array.from(document.querySelectorAll('.parentItemAdsMeta'));

  allItems.forEach(item => {
    const valCreative = Number(item.getAttribute(attributeCreative));
    const valShows = Number(item.getAttribute(attributeShows));
    const showCreative = item.classList.contains(classBySort) && !isNaN(valCreative) && valCreative >= filter.limitCreative;
    const showSows = item.classList.contains(classBySort) && !isNaN(valShows) && valShows >= filter.limit;

    if (filter.showOnlyWithShowCount && showSows) {
      item.style.display = '';
    } else {
      item.style.display = showCreative && showSows ? '' : 'none';
    }
  });
};

