const getDataAD = (id) => {
  if (!id) {
    return;
  }
  const rawData = utils.extractPageData();

  const ad = rawData.find(data => data?.ad_archive_id === id);

  if (ad) {
    const data = utils.processAdData([ad]);
    return data.length && data[0];
  }

  const dataAD = ads.find(data => data?.ad_archive_id === id);

  if (dataAD) {
    return dataAD;
  }
};

const downloadContent = async (e, isModal) => {
  try {
    const parentNode = e?.target?.parentNode?.parentNode?.parentNode.parentNode.parentNode;
    const searchId = parentNode.querySelector(".x8t9es0.xw23nyj.xo1l8bm.x63nzvj.x108nfp6.xq9mrsl.x1h4wwuj.xeuugli")?.textContent.trim().split(" ");

    const id = searchId && searchId[searchId.length - 1];

    const adData = getDataAD(id);

    const {useImg, useVideo, effImgOptions, effVideoOptions} = await getEffectiveDownloadOptions({
      imgFallback: imgOptions,
      videoFallback: videoOptions,
    });

    if (!parentNode) {
      return;
    }

    const isImages = isModal ? e.target.parentNode.parentNode.parentNode.parentNode?.querySelectorAll('.xz62fqu.x19kjcj4') : parentNode?.querySelectorAll('.x1ll5gia.x19kjcj4');
    const isVideos = parentNode?.querySelectorAll('.xh8yej3 div video');

    if (useImg) {
      if (isImages?.length) {
        for (const image of Array.from(isImages)) {
          const src = image.getAttribute("src");
          if (!src) continue;

          const response = await fetch(src, { credentials: 'omit' });
          const originalBlob = await response.blob();

          const detectedType = utils.chooseTypeByExtension(src, response.headers.get('Content-Type') || originalBlob.type);
          const finalType = detectedType || imgOptions?.type;

          const processedBlob = await utils.processImageBlob(originalBlob, {
            ...effImgOptions,
            type: finalType,
          });
          // utils.downloadBlob(processedBlob, `image - ${Date.now()}.jpg`);
          utils.downloadBlob(processedBlob, `image - ${Date.now()}.${utils.extForMime(finalType)}`);
        }
      }
    } else {
      if (isImages?.length) {
        const res = await Promise.all(Array.from(isImages).map(async image => {
          const src = image.getAttribute("src")
          const response = await fetch(src);
          const data = await response.blob();
          return data;
        }));

        res.map(data => {
          const ref = document.createElement("a");
          ref.href = URL.createObjectURL(data);
          ref.download = `image - ${Date.now()}.jpg`;
          ref.click();
        })
      }
    }

    if (useVideo) {
      if (isVideos?.length) {
        // кнопка, по которой кликнули (локальный прогресс именно на ней)
        const btn = e?.target?.closest('.buttonDowlVideo') || e?.target;
        const ui = makeButtonProgress(btn);

        // утилиты прогресса
        let totalTasks = 0;     // сколько всего единиц работы (картинок + видео)
        let finishedTasks = 0;  // сколько задач завершено
        let currentOverallPct = 0;

        // пересчёт общего процента: finished + доля текущего
        const setOverall = (partialPctOfCurrentItem = 0) => {
          // каждый item даёт равный вклад = 100/totalTasks
          const perItemWeight = totalTasks > 0 ? (100 / totalTasks) : 100;
          const pct = Math.max(0, Math.min(100,
            finishedTasks * perItemWeight + partialPctOfCurrentItem * (perItemWeight / 100)
          ));
          currentOverallPct = pct;
          ui.set(pct);
        };
        const hasHD = adData?.videoURLs?.length || adData?.video_hd_url;

        for (const [index, video] of Array.from(isVideos).entries()) {
          const src = hasHD && (adData?.video_hd_url || adData?.videoURLs?.[index]?.video_hd_url)
            ? (adData?.video_hd_url || adData?.videoURLs?.[index]?.video_hd_url)
            : video.getAttribute('src');
          if (!src) continue;

          const resp = await fetch(src, { credentials: 'omit' });
          const originalBlob = await resp.blob();
          // пробрасываем onProgress из MediaRecorder в общий прогресс (доля текущего item)

          const {outBlob, format} = await processVideoWithMediaRecorder(originalBlob, {
            ...effVideoOptions,
            onProgress: ({ pct }) => setOverall(pct || 0)
          });

          // const formatFile = format === 'mp4' ? 'mp4' : 'webm';

          const mime = outBlob.type || 'video/webm';
          const ext  = extForMime(mime);

          utils.downloadBlob(outBlob, `video-processed-${Date.now()}.${ext}`);
          finishedTasks++;
          setOverall(0);
        }
        ui.done();

      }
    } else if (isVideos.length) {
      const isContainHDUrl = adData?.videoURLs?.length || adData?.video_hd_url;

      const res = await Promise.all(Array.from(isVideos).map(async (video, index) => {
        const src = isContainHDUrl && (adData?.video_hd_url || adData?.videoURLs[index]?.video_hd_url) ? adData?.video_hd_url || adData?.videoURLs[index]?.video_hd_url : video.getAttribute("src");
        const response = await fetch(src);
        const data = await response.blob();
        return data;
      }));

      res.map(data => {
        const ref = document.createElement("a");
        ref.href = URL.createObjectURL(data);
        ref.download = `video - ${Date.now()}.mp4`;
        ref.click();
      })
    }
  } catch (error) {
    console.log(error)
    alert("Error downloading video");
  }
};

