const checkIfNeedSort = () => {
  const currentItems = document.querySelectorAll('.parentItemAdsMeta');
  const currentCount = currentItems?.length;

  if (!currentCount) {
    return;
  }

  if (currentCount !== previousItemCount && !sortDisableRadio?.checked) {
    previousItemCount = currentCount;

    const sortType = utils.getSortType(
      sortByShowsRadio?.checked,
      sortByCreativeRadio?.checked
    );

    if (sortByShowsRadio?.checked || sortByCreativeRadio?.checked) {
      debouncedSort(sortType);
    }
  }
}

const updateDOM = async (processedAds, retryCount = 0) => {
  const MAX_RETRIES = 5;
  const RETRY_DELAY = 100;
  const searchBlock = document.querySelector('.x1dr75xp.xh8yej3 .x6s0dn4.x78zum5.x1q0g3np.xozqiw3.x2lwn1j.xeuugli.x1iyjqo2.x8va1my.xh8yej3');

  // if (!searchBlock) {
  //   return;
  // }

  if (!processedAds?.length) {
    return;
  }

  try {
    for (const adData of processedAds) {
      if (!adData.ad_archive_id) {
        console.warn('Ad missing archive ID:', adData);
        continue;
      }

      const containers = utils.findAdContainers(adData.ad_archive_id);

      if (containers.length === 0 && retryCount < MAX_RETRIES) {
        // If no containers found, retry after delay
        await new Promise(resolve => setTimeout(resolve, RETRY_DELAY));
        return updateDOM(processedAds, retryCount + 1);
      }

      containers.forEach(container => {
        if (!container?.parentNode?.classList?.contains('parentItemAdsMeta')) {
          container?.parentNode?.setAttribute('ad_id', adData.ad_archive_id);
          addBtnPage(container.parentNode);
          addReach(container.parentNode);
        }
      });
    }
  } catch (error) {

    console.error('Error in updateDOM:', error);
    if (!processedAds?.length) {
      return;
    }

    if (retryCount < MAX_RETRIES) {
      await new Promise(resolve => setTimeout(resolve, RETRY_DELAY));
      return updateDOM(processedAds, retryCount + 1);
    }
  }
}

