const setStatusFilters = () => {

  const btnToggleFBFilters = document.querySelector('.toggle-filters-btn');
  const filtersFB = document.querySelector(blockDefaultFBFilters);

  const filtersContainer = document.querySelector('.hide');
  const arrowWrapperBlock = document.querySelector('.arrowWrapper');

  function saveFiltersState(isCollapsed) {
    chrome.storage.local.set({ filtersCollapsed: isCollapsed });
  }

  function loadFiltersState(callback) {
    chrome.storage.local.get(['filtersCollapsed'], (result) => {
      callback(result.filtersCollapsed || false);
    });
  }

  if (!btnToggleFBFilters || !filtersFB) return;


  loadFiltersState((isCollapsed) => {
    if (isCollapsed) {
      filtersFB?.classList?.add('collapsed');
      arrowWrapperBlock.innerHTML = `Show FB filters<span class="arrow"></span> `;
    } else {
      filtersFB?.classList?.remove('collapsed');
      arrowWrapperBlock.innerHTML = `Hide FB filters<span class="arrow"></span>`;
    }

    filtersContainer?.classList?.remove('hide');
  });


  btnToggleFBFilters?.addEventListener('click', () => {
    const isCollapsed = filtersFB?.classList?.toggle('collapsed');

    if (isCollapsed) {
      arrowWrapperBlock.innerHTML = `Show FB filters<span class="arrow">▼</span>`;
    } else {
      arrowWrapperBlock.innerHTML = `Hide FB filters<span class="arrow">▲</span>`;
    }

    saveFiltersState(isCollapsed);
  });

  addFilters();
}


const showOnlyShowed = (isOnlyShowed, attributeName = 'data-shows') => {
  const allItems = Array.from(document.querySelectorAll('.parentItemAdsMeta'));

  const validItems = isOnlyShowed
    ? allItems.filter(item =>
      item.hasAttribute(attributeName) &&
      Number(item.getAttribute(attributeName)) === 0
    )
    : allItems.filter(item => item.classList.contains('none'));

  validItems.forEach(el => {
    if (isOnlyShowed) {
      el.classList.add('none'); // скрыть если значение атрибута = 0
    } else {
      el.classList.remove('none'); // показать обратно
    }
  });
};

